  1 │ /**
  2 │  * `nexus worktree <subcommand>`: one argument parser and dispatcher shared by the CLI command, the `/worktree` slash
  3 │  * command (REPL and sidecar) and the tests. Mutating subcommands are refused in read-only mode here as well as at the
  4 │  * two slash gates, so no entry point can reach them.
  5 │  */
  6 │ import { redactSecrets } from "../ui.js";
  7 │ import { homeDir, listWorktrees, pathOf, removeWorktrees, switchWorktree, WorktreeError, type CommandResult, type WorktreeContext } from "./core.js";
  8 │ import { copyIgnored } from "./copy.js";
  9 │ import { mergeWorktree, parseAge, pruneWorktrees } from "./merge.js";
 10 │ import { GitError } from "./git.js";
 11 │ import { WorktreePathError } from "./paths.js";
 12 │ 
 13 │ export interface RunContext {
 14 │   cwd: string;
 15 │   home?: string;
 16 │   readOnly?: boolean;
 17 │ }
 18 │ 
 19 │ interface Parsed { positionals: string[]; flags: Set<string>; values: Map<string, string> }
 20 │ 
 21 │ interface Spec { booleans: Record<string, string>; values: Record<string, string>; positional: string }
