177 │   if (included.length === 0) return [];
178 │   // Keep only what the repository's own ignore rules also cover.
179 │   const ignored = git(sourceRoot, ["check-ignore", "-z", "--stdin"], { input: included.join("\0") + "\0", allowFailure: true });
