  public createWorktree(taskId: string = `task-${randomUUID().slice(0, 8)}`, startPoint: string = "HEAD"): WorktreeCreateResult {
    if (!this.isGitRepo()) {
      throw new Error(`Cannot create worktree: ${this.workspace} is not a valid git repository.`);
